import { describe, it, expect } from 'vitest'
import {
  solveCurve, curveGeometry, tangentAzimuthFromChord, tangentAzimuthFromRadial,
  radiusFromDegreeOfCurve, degreeOfCurveFromRadius,
  type CurveElementId, type CurveElements,
} from './curve-cogo'
import { inverse, norm360, toMetres, UNITS } from './cogo'
import type { Position } from './types'

/**
 * The worked example every element is checked against: R = 400 ft, Δ = 60°.
 * Each figure below is exact in closed form and checkable by hand, which is the
 * point — a fixture generated by the code under test proves only that it is
 * self-consistent.
 *
 *   L = RΔ          = 400 × π/3      = 418.8790 ft
 *   T = R tan(Δ/2)  = 400 × tan30°   = 230.9401 ft
 *   C = 2R sin(Δ/2) = 800 × sin30°   = 400.0000 ft
 *   E = R(sec½Δ−1)  = 400 × 0.154701 =  61.8802 ft
 *   M = R(1−cos½Δ)  = 400 × 0.133975 =  53.5898 ft
 *   Dₐ (arc, 100 ft stations) = 100×180/π ÷ 400 = 14.32394°
 *   D꜀ (chord)               = 2 asin(50/400)  = 14.36151°
 */
const FT = (v: number): number => toMetres(v, 'ft')
const STATION = FT(100)

const EX = {
  radius: FT(400),
  delta: 60,
  arcLength: FT(418.8790205),
  chord: FT(400),
  tangent: FT(230.9401077),
  external: FT(61.8802154),
  midOrdinate: FT(53.5898385),
  degreeArc: 14.3239449,
  degreeChord: 14.3615123,
}

const near = (a: number, b: number, tolM = 1e-6): void => expect(Math.abs(a - b)).toBeLessThan(tolM)

describe('degree of curve', () => {
  it('matches both published definitions at R = 400 ft', () => {
    expect(degreeOfCurveFromRadius(EX.radius, STATION, 'arc')).toBeCloseTo(EX.degreeArc, 5)
    expect(degreeOfCurveFromRadius(EX.radius, STATION, 'chord')).toBeCloseTo(EX.degreeChord, 5)
  })

  it('round-trips back to the radius', () => {
    for (const def of ['arc', 'chord'] as const) {
      const d = degreeOfCurveFromRadius(EX.radius, STATION, def)
      near(radiusFromDegreeOfCurve(d, STATION, def)!, EX.radius, 1e-9)
    }
  })

  it('is not the same number under the two definitions', () => {
    // 3.8 minutes apart at this radius — small, and the difference between a
    // curve that closes on the plat and one that does not.
    expect(Math.abs(EX.degreeArc - EX.degreeChord) * 60).toBeGreaterThan(2)
  })
})

/**
 * Every pair of elements a plan might quote has to rebuild the same curve.
 * This is the property the whole solver exists for, and enumerating the pairs
 * is the only way to know it holds for the transcendental ones (L&C, L&M, C&E)
 * as well as for the closed-form ones.
 */
describe('solveCurve reconstructs one curve from any two of its elements', () => {
  const given: Record<string, number> = {
    radius: EX.radius,
    delta: EX.delta,
    arcLength: EX.arcLength,
    chord: EX.chord,
    tangent: EX.tangent,
    external: EX.external,
    midOrdinate: EX.midOrdinate,
  }
  const ids = Object.keys(given) as CurveElementId[]

  const pairs: [CurveElementId, CurveElementId][] = []
  for (let i = 0; i < ids.length; i++) {
    for (let j = i + 1; j < ids.length; j++) pairs.push([ids[i], ids[j]])
  }

  // Tangent + mid-ordinate fits two ORDINARY curves and is refused; it is
  // asserted separately below. Everything else must resolve — including radius
  // + chord, which fits a reflex partner the solver correctly sets aside.
  const ambiguous = new Set(['tangent|midOrdinate'])

  it.each(pairs.filter(([a, b]) => !ambiguous.has(`${a}|${b}`)))(
    'from %s and %s', (a, b) => {
      const res = solveCurve({
        turn: 'right', stationM: STATION,
        a: { id: a, value: given[a] },
        b: { id: b, value: given[b] },
      })
      expect(res.ok, res.ok ? '' : res.error).toBe(true)
      if (!res.ok) return
      // A tenth of a millimetre on the radius, a ten-thousandth of a degree on
      // the angle — far tighter than any plat is quoted to.
      near(res.value.radiusM, EX.radius, 1e-4)
      expect(res.value.deltaDeg).toBeCloseTo(EX.delta, 4)
      near(res.value.arcLengthM, EX.arcLength, 1e-4)
      near(res.value.chordM, EX.chord, 1e-4)
      near(res.value.tangentM!, EX.tangent, 1e-4)
      near(res.value.externalM!, EX.external, 1e-4)
      near(res.value.midOrdinateM, EX.midOrdinate, 1e-4)
    }
  )

  it('accepts a degree of curve in place of the radius', () => {
    const res = solveCurve({
      turn: 'right', stationM: STATION, degreeDefinition: 'arc',
      a: { id: 'degreeOfCurve', value: EX.degreeArc },
      b: { id: 'delta', value: EX.delta },
    })
    expect(res.ok).toBe(true)
    if (res.ok) near(res.value.radiusM, EX.radius, 1e-6)
  })

  it('reads the chord definition differently from the arc definition', () => {
    const arc = solveCurve({
      turn: 'right', stationM: STATION, degreeDefinition: 'arc',
      a: { id: 'degreeOfCurve', value: 8 }, b: { id: 'delta', value: 40 },
    })
    const chord = solveCurve({
      turn: 'right', stationM: STATION, degreeDefinition: 'chord',
      a: { id: 'degreeOfCurve', value: 8 }, b: { id: 'delta', value: 40 },
    })
    expect(arc.ok && chord.ok).toBe(true)
    if (!arc.ok || !chord.ok) return
    expect(Math.abs(arc.value.radiusM - chord.value.radiusM)).toBeGreaterThan(0.01)
  })
})

describe('solveCurve refuses what it cannot answer', () => {
  const ask = (a: CurveElementId, av: number, b: CurveElementId, bv: number) =>
    solveCurve({ turn: 'right', stationM: STATION, a: { id: a, value: av }, b: { id: b, value: bv } })

  it('names the ambiguity when two curves fit', () => {
    // T/M falls to a minimum near Δ = 138° and rises again, so a shallow curve
    // and a sharp one satisfy the same pair. Nothing in the numbers says which.
    const res = ask('tangent', EX.tangent, 'midOrdinate', EX.midOrdinate)
    expect(res.ok).toBe(false)
    if (res.ok) return
    expect(res.error).toMatch(/more than one curve/i)
    expect(res.error).toMatch(/60\.00°/)
    expect(res.error).toMatch(/Add a radius/i)
  })

  it('takes the ordinary curve when the only other fit is reflex', () => {
    // R = 400 ft with a 400 ft chord is a 60° curve OR a 300° one. A deed
    // quoting those two means the first, and the readout shows Δ = 60° so a
    // user who meant the other can see that they did not get it.
    const res = ask('radius', EX.radius, 'chord', EX.chord)
    expect(res.ok, res.ok ? '' : res.error).toBe(true)
    if (res.ok) expect(res.value.deltaDeg).toBeCloseTo(60, 4)
  })

  it('still reaches the reflex curve when the delta is typed', () => {
    const res = ask('radius', EX.radius, 'delta', 300)
    expect(res.ok).toBe(true)
    if (res.ok) near(res.value.chordM, EX.chord, 1e-4)
  })

  it('refuses a radius and a degree of curve as the same fact twice', () => {
    const res = ask('radius', EX.radius, 'degreeOfCurve', EX.degreeArc)
    expect(res.ok).toBe(false)
    if (!res.ok) expect(res.error).toMatch(/IS a radius/)
  })

  it('refuses a chord longer than the diameter, and says why', () => {
    const res = ask('radius', FT(100), 'chord', FT(500))
    expect(res.ok).toBe(false)
    if (!res.ok) expect(res.error).toMatch(/never be longer than twice the radius/)
  })

  it('refuses a tangent above Δ = 180°, where the tangents never meet', () => {
    const res = ask('delta', 220, 'tangent', FT(100))
    expect(res.ok).toBe(false)
    if (!res.ok) expect(res.error).toMatch(/never meet/)
  })

  it('refuses a delta outside 0–360', () => {
    expect(ask('delta', 0, 'radius', FT(400)).ok).toBe(false)
    expect(ask('delta', 400, 'radius', FT(400)).ok).toBe(false)
  })

  it('refuses the same element twice', () => {
    const res = ask('radius', FT(400), 'radius', FT(400))
    expect(res.ok).toBe(false)
    if (!res.ok) expect(res.error).toMatch(/given twice/)
  })

  it('refuses a negative or zero value', () => {
    expect(ask('radius', -5, 'delta', 60).ok).toBe(false)
  })

  // Above 180° a curve still has an arc, a chord and a mid-ordinate — the
  // solver must not treat the whole range past a half turn as an error.
  it('solves a reflex curve from the elements that still exist', () => {
    const res = ask('radius', FT(400), 'delta', 300)
    expect(res.ok).toBe(true)
    if (!res.ok) return
    expect(res.value.tangentM).toBeNull()
    expect(res.value.externalM).toBeNull()
    near(res.value.arcLengthM, FT(400) * 300 * (Math.PI / 180), 1e-6)
  })
})

describe('curveGeometry', () => {
  const pc: Position = [-122.4, 45]
  const solved = (turn: 'left' | 'right'): CurveElements => {
    const r = solveCurve({
      turn, stationM: STATION,
      a: { id: 'radius', value: EX.radius }, b: { id: 'delta', value: EX.delta },
    })
    if (!r.ok) throw new Error(r.error)
    return r.value
  }

  it.each(['right', 'left'] as const)('leaves PC on the tangent — %s turn', (turn) => {
    const g = curveGeometry(pc, 30, solved(turn))
    // A point a little way along the curve: the chord to it is the tangent,
    // turned by half the sweep so far. 1e-4 of a 60° curve is 0.006°, so the
    // chord is within 0.003° of the tangent — and it is 13 mm away rather than
    // the 13 MICROmetres t = 1e-7 would give, which is below Vincenty's own
    // 1e-12 radian convergence and comes back as noise.
    const justAfter = g.at(1e-4)
    expect(Math.abs(norm360(inverse(pc, justAfter).initialAzimuth - 30 + 180) - 180)).toBeLessThan(0.01)
  })

  it.each(['right', 'left'] as const)('arrives on the deflected tangent — %s turn', (turn) => {
    const g = curveGeometry(pc, 30, solved(turn))
    const expected = norm360(30 + (turn === 'right' ? 1 : -1) * EX.delta)
    expect(Math.abs(norm360(g.outAzimuthDeg - expected + 180) - 180)).toBeLessThan(0.01)
  })

  it('has the arc length and chord the elements promised', () => {
    const g = curveGeometry(pc, 30, solved('right'))
    let walked = 0
    let prev = g.at(0)
    for (let i = 1; i <= 4000; i++) {
      const p = g.at(i / 4000)
      walked += inverse(prev, p).distanceM
      prev = p
    }
    // Chord sum under-reads the arc by a vanishing amount at this step count.
    expect(Math.abs(walked - EX.arcLength)).toBeLessThan(0.001)
    expect(Math.abs(inverse(g.pc, g.pt).distanceM - EX.chord)).toBeLessThan(0.001)
  })

  it('starts exactly at PC', () => {
    // The assumption this replaces — that PC is a half turn back from the
    // centre — put the start of the curve 2 mm away from the point the
    // previous course ended on.
    const g = curveGeometry(pc, 30, solved('right'))
    expect(inverse(g.at(0), pc).distanceM).toBeLessThan(1e-4)
  })

  it('stays at a constant radius from its centre', () => {
    const g = curveGeometry(pc, 30, solved('right'))
    for (let i = 0; i <= 100; i++) {
      expect(Math.abs(inverse(g.centre, g.at(i / 100)).distanceM - EX.radius)).toBeLessThan(1e-3)
    }
  })

  it('turns the way it was told, and the two turns mirror', () => {
    const right = curveGeometry(pc, 0, solved('right'))
    const left = curveGeometry(pc, 0, solved('left'))
    // Heading due north: a right turn ends east of PC, a left turn west.
    expect(right.pt[0]).toBeGreaterThan(pc[0])
    expect(left.pt[0]).toBeLessThan(pc[0])
    expect(right.pt[1]).toBeCloseTo(left.pt[1], 6)
  })

  it('recovers its own tangent from the chord bearing it reports', () => {
    for (const turn of ['right', 'left'] as const) {
      for (const az of [0, 30, 175, 280, 359]) {
        const g = curveGeometry(pc, az, solved(turn))
        const back = tangentAzimuthFromChord(g.chordAzimuthDeg, EX.delta, turn)
        expect(Math.abs(norm360(back - az + 180) - 180)).toBeLessThan(0.01)
      }
    }
  })

  it('recovers its own tangent from the radial bearing to the centre', () => {
    for (const turn of ['right', 'left'] as const) {
      const g = curveGeometry(pc, 117, solved(turn))
      const radial = inverse(g.pc, g.centre).initialAzimuth
      const back = tangentAzimuthFromRadial(radial, turn)
      expect(Math.abs(norm360(back - 117 + 180) - 180)).toBeLessThan(0.01)
    }
  })
})

describe('the deed call from the plan', () => {
  /**
   * *"…along a curve to the right having a radius of 250.00 feet, a central
   * angle of 45°30'00", an arc length of 198.53 feet, a chord of
   * 193.36 feet bearing S22°45'00"W…"* — the arc length and the chord bearing are REDUNDANT on a
   * plat, which is exactly what makes them worth checking: they are how a
   * surveyor catches a typo, and the tool has to reproduce both.
   */
  it('reproduces the redundant figures the plat quotes', () => {
    const res = solveCurve({
      turn: 'right', stationM: toMetres(100, 'ft'),
      a: { id: 'radius', value: toMetres(250, 'ft') },
      b: { id: 'delta', value: 45.5 },
    })
    expect(res.ok).toBe(true)
    if (!res.ok) return
    expect(res.value.arcLengthM / UNITS.ft.toMetre).toBeCloseTo(198.53, 2)
    expect(res.value.chordM / UNITS.ft.toMetre).toBeCloseTo(193.36, 2)

    // Leaving on S 0°00' W (due south, azimuth 180) and turning right by 45°30'
    // puts the chord bearing half the deflection round: S 22°45' W.
    const g = curveGeometry([-122.4, 45], 180, res.value)
    expect(Math.abs(norm360(g.chordAzimuthDeg - (180 + 22.75) + 180) - 180)).toBeLessThan(0.01)
  })
})
